// Re-index only when the folder changed. "version" grows with every edit of a file.
const SUPPORTED = /^(application\/vnd\.google-apps\.(document|spreadsheet|presentation)|application\/pdf|text\/(plain|markdown|csv)|application\/vnd\.openxmlformats-officedocument\.wordprocessingml\.document)$/;
const files = $input.all().map(i => i.json).filter(f => f.id && SUPPORTED.test(f.mimeType || ''));
const fingerprint = files.map(f => f.id + ':' + f.version).sort().join('|');
const state = $getWorkflowStaticData('global');
if (!files.length || state.kb_fingerprint === fingerprint) return [];
return files.map(f => ({ json: { ...f, fingerprint } }));

// Saved only after the insert succeeded, so a failed run is retried next hour.
const fingerprint = $('Docs Changed?').first().json.fingerprint;
$getWorkflowStaticData('global').kb_fingerprint = fingerprint;
return [{ json: { files: $('Docs Changed?').all().length, chunks: $input.all().length, synced_at: $now.toISO() } }];

// Last 7 days: chats, answers, knowledge gaps and tickets.
const since = DateTime.now().minus({ days: 7 });
const recent = r => { const d = DateTime.fromISO(String(r.created_at || r['Created At'] || '')); return d.isValid && d >= since; };
const log = $('Get Support Log').all().map(i => i.json).filter(recent);
const turns = log.filter(r => r.kind === 'turn');
const gaps = log.filter(r => r.kind === 'gap');
const tickets = $('Read Tickets').all().map(i => i.json).filter(r => r['Ticket ID'] && recent(r));
return [{ json: {
  conversations: new Set(turns.map(r => r.session_id)).size,
  questions: turns.length,
  gaps: gaps.length,
  tickets: tickets.length,
  urgent_tickets: tickets.filter(t => t.Priority === 'urgent').length,
  sample_questions: turns.slice(0, 80).map(r => r.question),
  gap_questions: gaps.map(r => r.question),
  ticket_summaries: tickets.map(t => t.Category + ' · ' + t.Priority + ' · ' + t.Summary),
} }];

parameters.message:
={{ (() => {
  const s = $('Summarize Week').first().json;
  const a = $json.output;
  const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const auto = s.questions ? Math.round((1 - s.tickets / Math.max(1, s.conversations)) * 100) : 0;
  let html = '<div style="font-family:Arial,sans-serif;font-size:14px">' +
    '<p>' + s.conversations + ' conversations · ' + s.questions + ' questions · ' + s.tickets + ' tickets (' + s.urgent_tickets + ' urgent) · ' + s.gaps + ' unanswered · about ' + auto + '% solved without a ticket</p>';
  if (a) {
    html += '<h3 style="margin:12px 0 4px">' + esc(a.headline) + '</h3><p>Overall mood: ' + esc(a.sentiment) + '</p>' +
      '<h4>Top topics</h4><ul>' + a.top_topics.map(t => '<li>' + esc(t.topic) + ' (' + t.count + ') · <i>' + esc(t.example) + '</i></li>').join('') + '</ul>' +
      '<h4>Complaints</h4><ul>' + a.complaints.map(c => '<li><b>' + esc(c.issue) + '</b> (' + c.count + '): ' + esc(c.suggested_fix) + '</li>').join('') + '</ul>' +
      '<h4>Add to the help docs</h4><ul>' + a.knowledge_gaps.map(g => '<li><b>' + esc(g.question) + '</b> · ' + esc(g.doc_update) + '</li>').join('') + '</ul>' +
      '<h4>Actions</h4><ol>' + a.actions.map(x => '<li>' + esc(x) + '</li>').join('') + '</ol>';
  } else {
    html += '<h4>Unanswered questions</h4><ul>' + s.gap_questions.map(q => '<li>' + esc(q) + '</li>').join('') + '</ul><p style="color:#666">The AI analysis failed this week; the numbers above are complete.</p>';
  }
  return html + '</div>';
})() }}

assignments.value:
={{ (() => {
  const t = $('On Workflow Error').first().json;
  const msg = t.execution?.error?.message ?? t.trigger?.error?.message ?? '';
  if (msg.includes('[CRITICAL]')) return 'CRITICAL';
  if (msg.includes('[WARNING]')) return 'WARNING';
  return 'ERROR';
})() }}
